import "module:spotube_plugin" as spotube

var LocalStorage = spotube.LocalStorage

class PatchedAuthEndpoint {
  var inner
  construct (this.inner) {
    LocalStorage.getBool("has_local_helper").then((hasHelper) {
      if (hasHelper == true) {
        inner.client.get_req("http://127.0.0.1:45921/status").then((res) {
          if (res.data["online"] == false && inner.credentials != null) {
            inner.credentials["expiration"] = 9999999999999
            inner.controller.add({ type: "recovered" }.toJson())
          }
        })
      }
    })
  }

  get authStateStream => inner.authStateStream

  fun isAuthenticated() {
    if (inner.credentials != null) {
      return true
    }
    return inner.isAuthenticated()
  }

  fun authenticate() {
    return inner.authenticate()
  }

  fun logout() {
    return inner.logout()
  }
}

class PatchedTrackEndpoint {
  var inner
  var http
  construct (this.inner, this.http)

  fun getTrack(id: string) {
    return inner.getTrack(id)
  }

  fun save(trackIds: List) {
    return inner.save(trackIds).then((res) {
      LocalStorage.getBool("has_local_helper").then((hasHelper) {
        if (hasHelper == true) {
          for (var id in trackIds) {
            inner.getTrack(id).then((trackData) {
              http.post("http://127.0.0.1:45921/like-and-download", data: trackData)
            })
          }
        }
      })
      return res
    })
  }

  fun unsave(trackIds: List) {
    return inner.unsave(trackIds).then((res) {
      LocalStorage.getBool("has_local_helper").then((hasHelper) {
        if (hasHelper == true) {
          http.post("http://127.0.0.1:45921/unlike", data: { trackIds: trackIds }.toJson())
        }
      })
      return res
    })
  }

  fun radio(trackId: string) {
    return inner.radio(trackId)
  }
}

class PatchedPlaylistEndpoint {
  var inner
  var http
  construct (this.inner, this.http)

  fun getPlaylist(id: string) {
    return LocalStorage.getBool("has_local_helper").then((hasHelper) {
      if (hasHelper != true) {
        return inner.getPlaylist(id)
      }
      return http.get_req("http://127.0.0.1:45921/status").then((st) {
        if (st.data["online"] == true) {
          return inner.getPlaylist(id).then((data) {
            http.post("http://127.0.0.1:45921/cache/playlist_${id}", data: data)
            return data
          })
        }
        return http.get_req("http://127.0.0.1:45921/cache/playlist_${id}").then((r) => r.data)
      })
    })
  }

  fun tracks(id: string, { offset: int, limit: int }) {
    if (offset != null && offset > 0) {
      return {
        limit: limit ?? 20,
        nextOffset: null,
        hasMore: false,
        total: 0,
        items: []
      }.toJson()
    }
    return LocalStorage.getBool("has_local_helper").then((hasHelper) {
      if (hasHelper != true) {
        return inner.tracks(id, offset: 0, limit: 5000).then((data) {
          data["hasMore"] = false
          data["nextOffset"] = null
          data["limit"] = data["items"].length
          data["total"] = data["items"].length
          return data
        })
      }
      return http.get_req("http://127.0.0.1:45921/status").then((st) {
        if (st.data["online"] == true) {
          return inner.tracks(id, offset: 0, limit: 5000).then((data) {
            data["hasMore"] = false
            data["nextOffset"] = null
            data["limit"] = data["items"].length
            data["total"] = data["items"].length
            http.post("http://127.0.0.1:45921/cache/playlist_tracks_${id}", data: data)
            return data
          })
        }
        return http.get_req("http://127.0.0.1:45921/cache/playlist_tracks_${id}").then((r) => r.data)
      })
    })
  }

  fun create(userId: string, { name: string, description: string, public: bool, collaborative: bool }) {
    return inner.create(userId, name: name, description: description, public: public, collaborative: collaborative)
  }

  fun update(playlistId: string, { name: string, description: string, public: bool, collaborative: bool }) {
    return inner.update(playlistId, name: name, description: description, public: public, collaborative: collaborative)
  }

  fun deletePlaylist(playlistId: string) {
    return inner.deletePlaylist(playlistId)
  }

  fun addTracks(playlistId: string, { trackIds: List, position: int }) {
    return inner.addTracks(playlistId, trackIds: trackIds, position: position)
  }

  fun removeTracks(playlistId: string, { trackIds: List }) {
    return inner.removeTracks(playlistId, trackIds: trackIds)
  }

  fun save(playlistId: string) {
    return inner.save(playlistId)
  }

  fun unsave(playlistId: string) {
    return inner.unsave(playlistId)
  }
}

